// Native rollback snapshots for the fixed-memory NP21 build.
// Exact heap checkpoints use a bounded frame pool, with verified zero pages
// omitted where SIMD is available. Files, bridge state and globals also rewind.
const PAGE=4096;
// Match TH04: one checkpoint per predicted frame in the 12-frame window.
const MAX_SNAPSHOTS=13;
// A pure read-only SIMD helper checks every byte of a 4 KiB page. It imports
// the existing memory, so it needs neither scratch heap space nor globals.
// Generated by tools/build_snapshot_zero.cjs. Older engines keep full copies.
const ZERO_PAGE_WASM=new Uint8Array([0,97,115,109,1,0,0,0,1,6,1,96,1,127,1,127,2,16,1,3,101,110,118,6,109,101,109,111,114,121,2,0,200,2,3,2,1,0,7,8,1,4,122,101,114,111,0,0,10,104,1,102,1,1,127,32,0,65,128,32,106,33,1,3,64,32,0,253,0,4,0,32,0,253,0,4,16,253,80,32,0,253,0,4,32,253,80,32,0,253,0,4,48,253,80,32,0,253,0,4,64,253,80,32,0,253,0,4,80,253,80,32,0,253,0,4,96,253,80,32,0,253,0,4,112,253,80,253,83,4,64,65,0,15,11,32,0,65,128,1,106,33,0,32,0,32,1,73,13,0,11,65,1,11]);
let zeroPageModule;
function memorySnapshots(module,nativeMemory){
  const memoryBytes=module.HEAPU8.length,pool=[];
  let zeroPage=null,allocated=0,peak=0;
  if(nativeMemory instanceof WebAssembly.Memory&&nativeMemory.buffer===module.HEAPU8.buffer){
    try{
      zeroPageModule??=WebAssembly.validate(ZERO_PAGE_WASM)?new WebAssembly.Module(ZERO_PAGE_WASM):false;
      if(zeroPageModule)zeroPage=new WebAssembly.Instance(zeroPageModule,{env:{memory:nativeMemory}}).exports.zero;
    }catch{ /* Preserve the full-copy path when SIMD/imports are unavailable. */ }
  }
  return {
    capture(){
      const heap=module.HEAPU8;
      let runs=null,used=memoryBytes;
      if(zeroPage){
        runs=[];used=0;let start=-1;
        for(let at=0;at<memoryBytes;at+=PAGE){
          if(!zeroPage(at)){if(start<0)start=at;}
          else if(start>=0){runs.push([start,at]);used+=at-start;start=-1;}
        }
        if(start>=0){runs.push([start,memoryBytes]);used+=memoryBytes-start;}
      }
      let data=pool.pop();
      if(!data||data.length<used){
        allocated-=data?.length||0;
        data=new Uint8Array(Math.ceil(used/65536)*65536);allocated+=data.length;
      }
      if(runs){let to=0;for(const [start,end]of runs){data.set(heap.subarray(start,end),to);to+=end-start;}}
      else data.set(heap);
      peak=Math.max(peak,allocated);
      return {data,runs};
    },
    restore({data,runs}){
      const heap=module.HEAPU8;
      if(!runs){heap.set(data);return;}
      let from=0,last=0;
      for(const [start,end]of runs){
        heap.fill(0,last,start);heap.set(data.subarray(from,from+end-start),start);
        from+=end-start;last=end;
      }
      heap.fill(0,last);
    },
    release(saved){pool.push(saved.data);},
    info(){return {snapshotBytes:peak,snapshotFormat:zeroPage?'zero-pages':'full'};}
  };
}
const copyBag=object=>Object.fromEntries(Object.entries(object).map(([k,v])=>[k,Array.isArray(v)?v.slice():v]));
function restoreBag(object,bag){
  for(const key of Object.keys(object))if(!Object.hasOwn(bag,key))delete object[key];
  Object.assign(object,bag);
}

export function createNativeSnapshots({module,fs,memfs,tty,host,exports,readBridge,writeBridge}){
  const frames=new Map();
  let active=null;
  const nativeGlobals=['__rollback_g0','__rollback_g1'].map(key=>exports()[key]);
  if(nativeGlobals.some(g=>!(g instanceof WebAssembly.Global)))throw Error('NP21 回滚全局状态接口缺失');
  const memoryBytes=module.HEAPU8.length;
  if(memoryBytes!==328*65536)throw Error('NP21 回滚内存布局变化');
  const memory=memorySnapshots(module,exports().Ld);

  function journal(buffer,position,length){
    if(!active||!buffer||!length)return;
    let pages=active.writes.get(buffer);
    if(!pages){pages=new Map();active.writes.set(buffer,pages);}
    const end=Math.min(buffer.length,position+length);
    for(let at=Math.floor(position/PAGE)*PAGE;at<end;at+=PAGE){
      if(!pages.has(at))pages.set(at,buffer.slice(at,Math.min(at+PAGE,buffer.length)));
    }
  }
  const write=memfs.stream_ops.write;
  memfs.stream_ops.write=function(stream,buffer,offset,length,position,canOwn){
    journal(stream.node.contents,position,length);
    return write.call(this,stream,buffer,offset,length,position,canOwn);
  };
  if(memfs.ops_table)memfs.ops_table.file.stream.write=memfs.stream_ops.write;

  function captureFs(){
    const nodes=new Map();
    function visit(node){
      if(!node||nodes.has(node))return;
      const bag=copyBag(node);
      if(fs.isDir(node.mode)){
        bag.contents={...node.contents};
        for(const child of Object.values(node.contents))visit(child);
      }
      nodes.set(node,bag);
    }
    visit(fs.root);
    const streams=fs.streams.slice(),streamState=new Map(),shared=new Map();
    for(const stream of streams)if(stream){
      visit(stream.node);streamState.set(stream,copyBag(stream));
      if(stream.shared)shared.set(stream.shared,copyBag(stream.shared));
    }
    return {nodes,streams,streamState,shared,nameTable:fs.nameTable.slice(),
      nextInode:fs.nextInode,currentPath:fs.currentPath,
      terminals:Object.values(tty.ttys).filter(Boolean).map(t=>[t,t.input.slice(),t.output.slice()])};
  }
  function restoreFs(saved){
    for(const [node,bag]of saved.nodes)restoreBag(node,bag);
    for(const [stream,bag]of saved.streamState)restoreBag(stream,bag);
    for(const [shared,bag]of saved.shared)restoreBag(shared,bag);
    fs.streams=saved.streams.slice();fs.nameTable=saved.nameTable.slice();
    fs.nextInode=saved.nextInode;fs.currentPath=saved.currentPath;
    for(const [terminal,input,output]of saved.terminals){terminal.input=input.slice();terminal.output=output.slice();}
  }
  function undo(saved){
    for(const [buffer,pages]of saved.writes)for(const [at,data]of pages){
      if(buffer.set)buffer.set(data,at);else for(let i=0;i<data.length;i++)buffer[at+i]=data[i];
    }
  }
  function release(frame){const saved=frames.get(frame);if(saved){memory.release(saved.memory);frames.delete(frame);}}
  return {
    capture(frame){
      if(active)throw Error('NP21 上一回滚帧尚未结束');
      if(frames.has(frame))throw Error(`NP21 回滚快照重复：${frame}`);
      if(frames.size>=MAX_SNAPSHOTS)throw Error('NP21 回滚快照窗口越界');
      if(module.HEAPU8.length!==memoryBytes)throw Error('回滚期间模拟器内存大小变化');
      const saved={memory:memory.capture(),globals:nativeGlobals.map(g=>g.value),files:captureFs(),
        bridge:readBridge(),clock:host.capture(),writes:new Map()};
      frames.set(frame,saved);active=saved;
    },
    seal(){active=null;},
    restore(frame){
      active=null;
      const saved=frames.get(frame);if(!saved)throw Error(`回滚快照已过期：${frame}`);
      for(const key of [...frames.keys()].sort((a,b)=>b-a))if(key>=frame)undo(frames.get(key));
      memory.restore(saved.memory);saved.globals.forEach((v,i)=>{nativeGlobals[i].value=v;});
      restoreFs(saved.files);writeBridge(saved.bridge);host.restore(saved.clock);
      for(const key of [...frames.keys()])if(key>=frame)release(key);
    },
    confirm(prefix){for(const frame of frames.keys())if(frame<prefix)release(frame);},
    info(){return {...memory.info(),snapshots:frames.size};}
  };
}
